	public static function maisto_uzsakymas( $o ) {
		global $wpdb;
		$t   = $wpdb->prefix . 'ps_refill_tracking';
		$ids = array();
		foreach ( $o->get_items() as $it ) {
			$ids[] = (int) $it->get_product_id();
			$b = (int) get_post_meta( (int) $it->get_product_id(), '_dp_base_product_id', true );
			if ( $b ) { $ids[] = $b; }
		}
		$ids = array_values( array_filter( array_unique( $ids ) ) );
		if ( ! $ids ) { return false; }
		$uid = (int) $o->get_customer_id();
		$in  = implode( ',', array_map( 'intval', $ids ) );
		$n   = $uid
			? (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM $t WHERE user_id=%d AND product_id IN ($in)", $uid ) )
			: (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM $t WHERE last_order_id=%d", $o->get_id() ) );
		return $n > 0;
	}
}
